/**
 * The two outer-shell looks every content card in this app uses. Deliberately just two -- anything
 * that needs a third (the sector heatmap tiles, the pillar score headers, the theme picker's preset
 * swatches) owns a background a signal color or an external caller controls, which is a different
 * thing from "which of the app's two standard card looks does this use," and stays a plain `Card`
 * rather than being forced in here.
 *
 * There used to be a third, `NEUTRAL` (white/elevated surface, for VIX/Fear & Greed/Put-Call), kept
 * visually distinct from `DATA`'s accent-tinted price cards on the theory that a computed reading
 * shouldn't look like raw data. Retired once that distinction stopped being wanted -- those cards
 * moved onto plain `DATA`, the same tinted background and border every other price card already uses.
 */
enum class PulseCardStyle {
    /** Raw or computed readings -- prices, ratios, VIX, Fear & Greed, Put/Call. `surfaceTinted`, hairline border. */
    DATA,

    /** Curated, AI-generated, or externally-sourced content -- briefings, verdicts, news, disclaimers. `accentSurfaceStrong`, hairline border. */
    SYNTHESIS
}

/**
 * 💡 THOUGHT PROCESS:
 * Before this, every card in the app hand-rolled its own `Card(colors = ..., border = ..., shape =
 * ...)` -- and a large fraction of them (every card in Insights and Summary, plus Indicators' AI
 * briefing) were still doing so with `MaterialTheme.colorScheme.secondaryContainer.copy(alpha =
 * 0.4f)`, a leftover from before this app had its own token system at all. Changing "what a card's
 * background looks like" meant hunting down every one of those call sites individually, and it was
 * easy for a new card to copy the stale pattern instead of the current one (which is exactly what
 * kept happening).
 *
 * This collapses that down to two outer looks (`PulseCardStyle`), each resolving to one
 * background + border + shape combination, defined in exactly one place. Only the OUTER shell is
 * standardized here -- every card's inner content (what it actually says, its own icons, dividers,
 * colored stripes, pills) stays exactly as varied as it already was and is untouched by this;
 * `content` has the same `ColumnScope` signature `Card` itself exposes, so a card whose top-level
 * child is a `Row` (a colored side-stripe layout, for instance) works exactly as before.
 *
 * `shape` defaults per style rather than being a single global default: `DATA` cards (price tiles,
 * computed-reading cards) use the larger `corner_radius_card_large`, while `SYNTHESIS` cards
 * (briefings, articles, verdicts) use the smaller `corner_radius_card` -- matching what every card in
 * each category already used before this consolidation, not a new choice.
 */
@Composable
fun PulseCard(
    style: PulseCardStyle,
    modifier: Modifier = Modifier,
    shape: Shape = RoundedCornerShape(
        dimensionResource(
            id = if (style == PulseCardStyle.SYNTHESIS) R.dimen.corner_radius_card else R.dimen.corner_radius_card_large
        )
    ),
    onClick: (() -> Unit)? = null,
    content: @Composable ColumnScope.() -> Unit
) {
    val pulseColors = LocalPulseColors.current

    val containerColor = when (style) {
        PulseCardStyle.DATA -> pulseColors.surfaceTinted
        PulseCardStyle.SYNTHESIS -> pulseColors.accentSurfaceStrong
    }
    // 💡 Both styles get the same hairline border now -- DATA didn't used to (it was the one
    // style with `border = null`), until VIX/Fear & Greed/Put-Call moved onto it and brought their
    // border with them.
    val border = BorderStroke(dimensionResource(id = R.dimen.border_thin), pulseColors.accentSurfaceBorder)
    val colors = CardDefaults.cardColors(containerColor = containerColor)
    val cardModifier = if (onClick != null) modifier.clickable(onClick = onClick) else modifier

    Card(
        colors = colors,
        border = border,
        shape = shape,
        modifier = cardModifier,
        content = content
    )
}

